# Open the selected claims together, in list order; responds with how many opened and refused, and the claims.
open:
  class: net.officefloor.hq.app.claim.BulkOpenClaims
  govern: [ transaction ]
# Change a claim's status: {change} is open, settle, void, approve or reject (with {"reason"} in the body). Responds with the sheet's claims.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Opens each selected claim in list order (people in the order they were added, newest claim first within a
 * person), so they are numbered in that order; one that cannot be opened is left as it is and counted refused.
 */
public class BulkOpenClaims {
    public void open(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @RequestBody BulkOpenRequest request, Claims claims, People people, ClaimStatusChanger changer,
            ObjectResponse<BulkOpenResponse> response) {
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.id(), personOrder.size());
        }
        List<Claim> selected = new ArrayList<>();
        int refused = 0;
        for (Long id : new LinkedHashSet<>(request == null || request.claims() == null ? List.of() : request.claims())) {
            Claim claim = id == null ? null : claims.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.person(), Integer.MAX_VALUE))
                .thenComparing(Claim::id, Comparator.reverseOrder()));
        int opened = 0;
        for (Claim claim : selected) {
            try {
                // Re-read so each claim is opened as the store holds it after the ones before it.
                changer.change(sheet, user, claims.find(sheet, claim.id()), ClaimStatusChange.OPEN);
                opened++;
            } catch (InvalidClaimStatusChangeException refusal) {
                refused++;
            }
        }
        response.send(new BulkOpenResponse(opened, refused, claims.list(sheet)));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** Body of POST /api/sheets/{sheet}/claims/bulk-open: the ids of the selected claims. */
public record BulkOpenRequest(List<Long> claims) {
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** How many of the selected claims were opened and how many refused, with the sheet's claims after. */
public record BulkOpenResponse(int opened, int refused, List<Claim> claims) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
 *  claim's own status buttons and the bulk actions. */
@Service
public class ClaimStatusChanger {

    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Periods periods;
    private final Roles roles;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;
    private final Rollup rollup;
    private final ClaimLog log;

    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log) {
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.roles = roles;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
        this.rollup = rollup;
        this.log = log;
