import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey, claimsPath } from './claims';
import type { Claim } from './claims';
import { clearSelectedClaims, useSelectedClaims } from './selection';

type BulkOpened = { opened: number; refused: number; claims: Claim[] };

// Opens the selected claims together: the server opens each that can be, numbering them in list order (people in
// the order they were added, newest claim first), and leaves the rest as they are. Shows how many of each.
function BulkOpen({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const selected = useSelectedClaims(sheet);
  const open = useMutation({
    mutationFn: (ids: number[]) => postJson<BulkOpened>(byUser(`${claimsPath(sheet)}/bulk-open`, user), { claims: ids }),
    onSuccess: (result) => {
      queryClient.setQueryData(claimsKey(sheet), result.claims);
      clearSelectedClaims(sheet);
    },
  });
  const act = useSubmitOnce(open);

  return (
    <p>
      Selected claims: {selected.size}{' '}
      <button type="button" data-testid="bulk-open" disabled={open.isPending} onClick={() => act([...selected])}>
        Open selected
      </button>
      {open.isSuccess && (
        <>
          {' '}Opened <strong data-testid="bulk-opened">{open.data.opened}</strong>, refused{' '}
          <strong data-testid="bulk-refused">{open.data.refused}</strong>
        </>
      )}
      {open.isError && (
        <span data-testid="bulk-open-error" role="alert">
          {' '}The bulk open failed.
        </span>
      )}
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: 21, Component: BulkOpen });
import { useSyncExternalStore } from 'react';

// The claims ticked for a bulk action, kept per sheet outside React so each claim's row and the bulk
// panel share it.
const selected = new Map<string, ReadonlySet<number>>();
const listeners = new Set<() => void>();
const NONE: ReadonlySet<number> = new Set();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function set(sheet: string, next: ReadonlySet<number>) {
  selected.set(sheet, next);
  listeners.forEach((l) => l());
}

/** The ids of the sheet's selected claims. */
export function useSelectedClaims(sheet: string): ReadonlySet<number> {
  return useSyncExternalStore(subscribe, () => selected.get(sheet) ?? NONE);
}

/** Ticks or unticks a claim. */
export function selectClaim(sheet: string, id: number, on: boolean) {
  const next = new Set(selected.get(sheet) ?? NONE);
  if (on) next.add(id);
  else next.delete(id);
  set(sheet, next);
}

/** Unticks every claim on the sheet. */
export function clearSelectedClaims(sheet: string) {
  set(sheet, NONE);
}

